entero operativa(registro Baliza b) { devolver b.activa == 1 Y b.energia >= 5 Y b.energia <= 20; }
entero aporte(registro Baliza b) {
  si (operativa(b)) { devolver b.energia - 2; }
  devolver 0;
}
registro Informe resumir(registro Baliza red[], entero n) {
  registro Informe total = {0, 0};
  para (entero i = 0; i < n; i = i + 1) {
    total.cantidad += operativa(red[i]); total.energia += aporte(red[i]);
  }
  devolver total;
}

