#ifndef FARO_H
#define FARO_H
typedef struct { int energia, activa; } Baliza;
typedef struct { int cantidad, energia; } Informe;
int operativa(Baliza b);
int aporte(Baliza b);
Informe resumir(const Baliza red[], int n);
#endif

main.c:
#include <stdio.h>
#include "faro.h"
int main(void) {
    FILE *f = fopen("lecturas.txt", "r");
    if (!f) { puts("SIN REGISTRO"); return 0; }
    Baliza red[8];
    int n = 0;
    while (n < 8 && fscanf(f, "%d %d", &red[n].energia, &red[n].activa) == 2) ++n;
    fclose(f);
    Informe resultado = resumir(red, n);
    printf("%d\n%d\n", resultado.cantidad, resultado.energia);
    return 0;
}
